-- Room schema version 1. Keep published versions immutable.
PRAGMA user_version = 1;
CREATE TABLE IF NOT EXISTS `anniversaries` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `title` TEXT NOT NULL, `note` TEXT, `category` TEXT NOT NULL, `occurred_at` INTEGER NOT NULL, `date_calendar` TEXT NOT NULL, `is_yearly` INTEGER NOT NULL, `lead_time_minutes` INTEGER NOT NULL, `is_enabled` INTEGER NOT NULL, `reminder_time_minutes` INTEGER NOT NULL, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_anniversaries_deleted_at_occurred_at` ON `anniversaries` (`deleted_at`, `occurred_at`);
CREATE TABLE IF NOT EXISTS `bills` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `title` TEXT NOT NULL, `original_amount_cents` INTEGER NOT NULL, `discount_amount_cents` INTEGER NOT NULL, `final_amount_cents` INTEGER NOT NULL, `transaction_type` TEXT NOT NULL, `category` TEXT NOT NULL, `payment_method` TEXT NOT NULL, `note` TEXT, `start_location` TEXT, `end_location` TEXT, `transport_lines` TEXT, `occurred_at` INTEGER NOT NULL, `image_data` BLOB, `image_asset_id` TEXT, `settlement_status` TEXT NOT NULL, `group_buy_valid_until` INTEGER, `redeemed_at` INTEGER, `refund_reason` TEXT, `stored_value_account_id` TEXT, `stored_value_effects` TEXT, `utility_account_number` TEXT, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`stored_value_account_id`) REFERENCES `stored_value_accounts`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(`image_asset_id`) REFERENCES `media_assets`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS `index_bills_deleted_at_occurred_at` ON `bills` (`deleted_at`, `occurred_at`);
CREATE INDEX IF NOT EXISTS `index_bills_image_asset_id` ON `bills` (`image_asset_id`);
CREATE INDEX IF NOT EXISTS `index_bills_stored_value_account_id` ON `bills` (`stored_value_account_id`);
CREATE TABLE IF NOT EXISTS `dataset_state` (`id` INTEGER NOT NULL, `activeScope` TEXT, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `decision_choice_records` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `collection_id` TEXT NOT NULL, `collection_title` TEXT NOT NULL, `option_id` TEXT NOT NULL, `option_title` TEXT NOT NULL, `option_detail` TEXT, `option_custom_info` TEXT, `option_image_data` BLOB, `option_image_asset_id` TEXT, `selected_at` INTEGER NOT NULL, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`option_image_asset_id`) REFERENCES `media_assets`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS `index_decision_choice_records_deleted_at_selected_at` ON `decision_choice_records` (`deleted_at`, `selected_at`);
CREATE INDEX IF NOT EXISTS `index_decision_choice_records_option_image_asset_id` ON `decision_choice_records` (`option_image_asset_id`);
CREATE TABLE IF NOT EXISTS `decision_collections` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `title` TEXT NOT NULL, `note` TEXT, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `decision_options` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `collection_id` TEXT NOT NULL, `title` TEXT NOT NULL, `detail` TEXT, `custom_info` TEXT, `image_data` BLOB, `image_asset_id` TEXT, `weight` INTEGER NOT NULL, `is_enabled` INTEGER NOT NULL, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`collection_id`) REFERENCES `decision_collections`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(`image_asset_id`) REFERENCES `media_assets`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS `index_decision_options_collection_id` ON `decision_options` (`collection_id`);
CREATE INDEX IF NOT EXISTS `index_decision_options_image_asset_id` ON `decision_options` (`image_asset_id`);
CREATE TABLE IF NOT EXISTS `diary_entries` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `title` TEXT NOT NULL, `content` TEXT NOT NULL, `mood` TEXT NOT NULL, `tags_json` TEXT NOT NULL, `occurred_at` INTEGER NOT NULL, `latitude` REAL, `longitude` REAL, `horizontal_accuracy` REAL, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_diary_entries_deleted_at_occurred_at` ON `diary_entries` (`deleted_at`, `occurred_at`);
CREATE TABLE IF NOT EXISTS `diary_links` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `diary_id` TEXT NOT NULL, `source_type` TEXT NOT NULL, `source_id` TEXT NOT NULL, `source_title` TEXT NOT NULL, `source_subtitle` TEXT, `source_icon` TEXT NOT NULL, `source_occurred_at` INTEGER, `snapshot_json` TEXT, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`diary_id`) REFERENCES `diary_entries`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS `index_diary_links_diary_id` ON `diary_links` (`diary_id`);
CREATE TABLE IF NOT EXISTS `diary_tags` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `name` TEXT NOT NULL, `note` TEXT, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `entity_snapshots` (`tableName` TEXT NOT NULL, `entityId` TEXT NOT NULL, `dataVersion` INTEGER NOT NULL, `json` TEXT NOT NULL, PRIMARY KEY(`tableName`, `entityId`));
CREATE TABLE IF NOT EXISTS `food_day_records` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `title` TEXT NOT NULL, `day_start_at` INTEGER NOT NULL, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_food_day_records_day_start_at` ON `food_day_records` (`day_start_at`);
CREATE TABLE IF NOT EXISTS `food_entries` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `title` TEXT NOT NULL, `meal_kind` TEXT NOT NULL, `portion` TEXT, `note` TEXT, `bill_id` TEXT, `bill_ids_json` TEXT NOT NULL, `occurred_at` INTEGER NOT NULL, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`bill_id`) REFERENCES `bills`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS `index_food_entries_bill_id` ON `food_entries` (`bill_id`);
CREATE INDEX IF NOT EXISTS `index_food_entries_deleted_at_occurred_at` ON `food_entries` (`deleted_at`, `occurred_at`);
CREATE TABLE IF NOT EXISTS `item_categories` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `name` TEXT NOT NULL, `note` TEXT, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `local_changes` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `mutationId` TEXT NOT NULL, `tableName` TEXT NOT NULL, `entityId` TEXT NOT NULL, `operation` TEXT NOT NULL, `dataVersion` INTEGER NOT NULL, `payloadJson` TEXT NOT NULL, `changedAt` INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `index_local_changes_mutationId` ON `local_changes` (`mutationId`);
CREATE TABLE IF NOT EXISTS `media_assets` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `kind` TEXT NOT NULL, `title` TEXT, `storage_backend` TEXT NOT NULL, `storage_key` TEXT NOT NULL, `mime_type` TEXT NOT NULL, `byte_count` INTEGER NOT NULL, `checksum` TEXT NOT NULL, `width` INTEGER, `height` INTEGER, `sort_order` INTEGER NOT NULL, `inline_data` BLOB, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_media_assets_deleted_at_sort_order` ON `media_assets` (`deleted_at`, `sort_order`);
CREATE INDEX IF NOT EXISTS `index_media_assets_storage_key` ON `media_assets` (`storage_key`);
CREATE TABLE IF NOT EXISTS `media_attachments` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `owner_type` TEXT NOT NULL, `owner_id` TEXT NOT NULL, `kind` TEXT NOT NULL, `title` TEXT, `asset_id` TEXT, `data` BLOB NOT NULL, `mime_type` TEXT NOT NULL, `duration_seconds` REAL, `width` INTEGER, `height` INTEGER, `sort_order` INTEGER NOT NULL, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`asset_id`) REFERENCES `media_assets`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS `index_media_attachments_asset_id` ON `media_attachments` (`asset_id`);
CREATE INDEX IF NOT EXISTS `index_media_attachments_owner_type_owner_id_deleted_at_sort_order` ON `media_attachments` (`owner_type`, `owner_id`, `deleted_at`, `sort_order`);
CREATE TABLE IF NOT EXISTS `notification_jobs` (`tableName` TEXT NOT NULL, `entityId` TEXT NOT NULL, `version` INTEGER NOT NULL, PRIMARY KEY(`tableName`, `entityId`));
CREATE TABLE IF NOT EXISTS `reminder_completions` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `reminder_id` TEXT NOT NULL, `date_key` TEXT NOT NULL, `completed_at` INTEGER NOT NULL, `kind` TEXT NOT NULL, `note` TEXT, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`reminder_id`) REFERENCES `reminders`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED);
CREATE UNIQUE INDEX IF NOT EXISTS `index_reminder_completions_reminder_id_date_key` ON `reminder_completions` (`reminder_id`, `date_key`);
CREATE TABLE IF NOT EXISTS `reminders` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `title` TEXT NOT NULL, `note` TEXT, `memory_icon` TEXT NOT NULL, `image_data` BLOB, `image_asset_id` TEXT, `scheduled_at` INTEGER NOT NULL, `lead_time_minutes` INTEGER NOT NULL, `is_enabled` INTEGER NOT NULL, `schedule_kind` TEXT NOT NULL, `end_at` INTEGER, `reminder_time_minutes` INTEGER NOT NULL, `weekdays` TEXT, `continuous_days` INTEGER NOT NULL, `completed_at` INTEGER, `imported_completed_days` INTEGER NOT NULL, `completed_date_keys` TEXT, `completion_records` TEXT, `ended_early_at` INTEGER, `early_end_reason` TEXT, `paused_at` INTEGER, `pause_reason` TEXT, `total_paused_milliseconds` INTEGER, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`image_asset_id`) REFERENCES `media_assets`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS `index_reminders_image_asset_id` ON `reminders` (`image_asset_id`);
CREATE TABLE IF NOT EXISTS `stored_items` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `category_id` TEXT, `title` TEXT NOT NULL, `location` TEXT NOT NULL, `note` TEXT, `tags` TEXT, `search_keywords` TEXT, `image_data` BLOB, `image_asset_id` TEXT, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`category_id`) REFERENCES `item_categories`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(`image_asset_id`) REFERENCES `media_assets`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS `index_stored_items_category_id` ON `stored_items` (`category_id`);
CREATE INDEX IF NOT EXISTS `index_stored_items_image_asset_id` ON `stored_items` (`image_asset_id`);
CREATE TABLE IF NOT EXISTS `stored_value_accounts` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `name` TEXT NOT NULL, `kind` TEXT NOT NULL, `balance_cents` INTEGER NOT NULL DEFAULT 0, `note` TEXT, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `stored_value_adjustments` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `account_id` TEXT NOT NULL, `amount_cents` INTEGER NOT NULL, `reason` TEXT NOT NULL, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`account_id`) REFERENCES `stored_value_accounts`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS `index_stored_value_adjustments_account_id` ON `stored_value_adjustments` (`account_id`);
CREATE TABLE IF NOT EXISTS `sync_conflicts` (`scope` TEXT NOT NULL, `mutationId` TEXT NOT NULL, `tableName` TEXT NOT NULL, `entityId` TEXT NOT NULL, `localJson` TEXT NOT NULL, `remoteJson` TEXT NOT NULL, `remoteVersion` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`scope`, `mutationId`), FOREIGN KEY(`scope`) REFERENCES `sync_targets`(`scope`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `sync_inbox` (`scope` TEXT NOT NULL, `version` INTEGER NOT NULL, `tableName` TEXT NOT NULL, `entityId` TEXT NOT NULL, `envelopeJson` TEXT NOT NULL, `applied` INTEGER NOT NULL, `lastError` TEXT, PRIMARY KEY(`scope`, `version`), FOREIGN KEY(`scope`) REFERENCES `sync_targets`(`scope`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_sync_inbox_scope_applied_version` ON `sync_inbox` (`scope`, `applied`, `version`);
CREATE TABLE IF NOT EXISTS `sync_media_jobs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `scope` TEXT NOT NULL, `direction` TEXT NOT NULL, `objectKey` TEXT NOT NULL, `checksum` TEXT NOT NULL, `size` INTEGER NOT NULL, `contentType` TEXT NOT NULL, `tableName` TEXT NOT NULL, `entityId` TEXT NOT NULL, `columnName` TEXT NOT NULL, `version` INTEGER NOT NULL, `storageKey` TEXT, `state` TEXT NOT NULL, `attemptCount` INTEGER NOT NULL, `nextAttemptAt` INTEGER NOT NULL, `lastError` TEXT, FOREIGN KEY(`scope`) REFERENCES `sync_targets`(`scope`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE UNIQUE INDEX IF NOT EXISTS `index_sync_media_jobs_scope_direction_tableName_entityId_columnName_checksum` ON `sync_media_jobs` (`scope`, `direction`, `tableName`, `entityId`, `columnName`, `checksum`);
CREATE TABLE IF NOT EXISTS `sync_outbox` (`scope` TEXT NOT NULL, `mutationId` TEXT NOT NULL, `tableName` TEXT NOT NULL, `entityId` TEXT NOT NULL, `operation` TEXT NOT NULL, `dataVersion` INTEGER NOT NULL, `payloadJson` TEXT NOT NULL, `baseVersion` INTEGER NOT NULL, `localChangeId` INTEGER NOT NULL, `predecessorId` TEXT, `preparedJson` TEXT, `status` TEXT NOT NULL, `serverVersion` INTEGER, `attemptCount` INTEGER NOT NULL, `lastError` TEXT, PRIMARY KEY(`scope`, `mutationId`), FOREIGN KEY(`scope`) REFERENCES `sync_targets`(`scope`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_sync_outbox_scope_status_tableName_entityId_localChangeId` ON `sync_outbox` (`scope`, `status`, `tableName`, `entityId`, `localChangeId`);
CREATE TABLE IF NOT EXISTS `sync_received_pages` (`scope` TEXT NOT NULL, `pageKey` TEXT NOT NULL, `body` BLOB NOT NULL, `sha256` TEXT NOT NULL, `received` INTEGER NOT NULL, PRIMARY KEY(`scope`, `pageKey`), FOREIGN KEY(`scope`) REFERENCES `sync_targets`(`scope`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `sync_rows` (`scope` TEXT NOT NULL, `tableName` TEXT NOT NULL, `entityId` TEXT NOT NULL, `version` INTEGER NOT NULL, `envelopeJson` TEXT NOT NULL, PRIMARY KEY(`scope`, `tableName`, `entityId`), FOREIGN KEY(`scope`) REFERENCES `sync_targets`(`scope`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `sync_targets` (`scope` TEXT NOT NULL, `connectionId` TEXT NOT NULL, `accountId` TEXT NOT NULL, `generation` TEXT NOT NULL, `receivedCursor` INTEGER NOT NULL, `appliedCursor` INTEGER NOT NULL, `bootstrapWatermark` INTEGER NOT NULL, `bootstrapAfter` INTEGER NOT NULL, `bootstrapComplete` INTEGER NOT NULL, `seeded` INTEGER NOT NULL, `failureCount` INTEGER NOT NULL, `nextAttemptAt` INTEGER NOT NULL, PRIMARY KEY(`scope`));
CREATE TABLE IF NOT EXISTS `track_points` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `track_id` TEXT NOT NULL, `latitude` REAL NOT NULL, `longitude` REAL NOT NULL, `altitude` REAL, `horizontal_acc` REAL, `vertical_acc` REAL, `speed_mps` REAL, `course_deg` REAL, `timestamp_ms` INTEGER NOT NULL, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`track_id`) REFERENCES `tracks`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS `index_track_points_track_id_deleted_at_timestamp_ms` ON `track_points` (`track_id`, `deleted_at`, `timestamp_ms`);
CREATE TABLE IF NOT EXISTS `track_segments` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `track_id` TEXT NOT NULL, `started_at` INTEGER NOT NULL, `ended_at` INTEGER NOT NULL, `distance_m` REAL NOT NULL, `duration_s` INTEGER NOT NULL, `avg_speed_mps` REAL, `max_speed_mps` REAL, `motion_type` TEXT NOT NULL, `source` TEXT NOT NULL, `confidence` REAL NOT NULL, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`track_id`) REFERENCES `tracks`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS `index_track_segments_track_id_deleted_at_started_at` ON `track_segments` (`track_id`, `deleted_at`, `started_at`);
CREATE TABLE IF NOT EXISTS `tracks` (`id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `deleted_at` INTEGER, `device_id` TEXT NOT NULL, `server_version` INTEGER, `name` TEXT NOT NULL, `started_at` INTEGER NOT NULL, `ended_at` INTEGER, `desired_accuracy_m` INTEGER NOT NULL, `distance_m` REAL NOT NULL, `duration_s` INTEGER NOT NULL, `avg_speed_mps` REAL, `max_speed_mps` REAL, `note` TEXT, `status` TEXT NOT NULL, `sync_status` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_tracks_deleted_at_started_at` ON `tracks` (`deleted_at`, `started_at`);
